from t1 import t
GPUSVC = "embedder + reranker containers, vector store, corpus database (read-only)"
PRE = "Pre-registered in commit 1; no metric, threshold or fixture changes afterwards (dated addendum only)."

# ---------------- W2: first GPU session, measurements only ----------------
t(id="EV-16", slug="baseline-main-corpus", title="Run the frozen main-corpus baselines (papers, books, legacy)",
  s=["S-16"], wave=2, area=["eval"], tier="Sonnet", size="M", gpu="y", services=GPUSVC,
  why="No baseline exists for the new papers-passage and causal-books sets, and every later A/B needs a measured reference on the same code and index; the first run is also the only moment the TEI truncation limit can be confirmed with one `/info` request (review S-16). Plain BM25 already reaches 0.96-0.98 paper recall on these sets, so only passage level and the title-ablated arm can show headroom (RV-3 F-1.3).",
  in_=["Run `run_baseline_main.sh papers books legacy` exactly as the GPU-day runbook step 1a specifies (about 654 queries, estimated 20-40 min), as a detached process (LESSONS section 7.3); then the BM25 floor (EV-15) beside it, the title-ablated arm and the strata report (EV-6).","One `/info` request to the embedder to confirm its truncation limit; record the value.","Report unmodified as a dated baseline document: passage-level headline (member-passage hit@10 and P@1, plus `passage_excerpt_hit`), paper recall as tripwire only, per-stratum Wilson intervals, `authority`/`edition`-style small strata labelled descriptive."],
  out=["Any A/B or config change (later tickets). The focus set (EV-17) and standards (EV-18). Re-grounding or editing a fixture. Quoting a precision-95 headline number (operator question F8)."],
  owns=["docs/eval-reports/<run-date>-main-baseline.md","docs/eval-reports/data/<run-date>-main-baseline/","docs/eval-reports/data/2026-11-10-papers-passage-gt/runs/ (own stamp only)"],
  commits=["stub: report skeleton citing the frozen main-corpus protocol and the stop conditions; hash file revision and git revision of the code under test recorded","detached run launched; MANIFEST committed when it starts (start time, collection, db, git revision, fixture hashes)","raw reports copied into the data dir with `n_errors` and `run_valid` shown","BM25 floor and title-ablated arm","report written; every number carries {metric, fixture, arm, pool depth, config}"],
  verify=["`conda run -n agent-rag-research python -m app.doctor --no-auto-start` exits 0 before and after","Run scripts print `check-hash` and `check-points` passes; the report's `ground_truth_sha256_12` equals the hash file's entry","`n_errors` is 0 and `run_valid` is true in every report (else the arm is invalid and is not read)"],
  accept="Per set (never averaged): passage-level hit@10 and P@1 with Wilson intervals, the BM25 floor beside it, the title-ablated paper recall, and stratum tables; the report hash equals the frozen hash; zero errors. The ceiling for each metric is printed with it (member hit@10 ceiling 1.00; paper recall tripwire headroom at most 2 items on the legacy 210-set). Falsified (run discarded) if a hash or point-count check fails or any error is a lock timeout.",
  deps=["EV-7","EV-8","EV-10","EV-11","EV-15","RQ-1","OP-5"], ext=["F3"], gates=["EV-17","EV-19","EV-20","EV-21","EV-22","RQ-3","CQ-11","RIDER-1"],
  needs_note="GPU free of the foreign model process (operator question F3); about 20-40 min GPU (estimate, not measured)",
  risk="A foreign GPU holder or a held lock starves the run. Mitigation: OP-5 names the holder; EV-10 invalidates a starved run; one GPU job at a time. The run only reads. Rollback: discard the run directory.",
  docs="Dated baseline report is the doc; PROJECT-STATUS section 3/6 via EP-4."),

