t(id="CQ-17", slug="bm25-weighting-in-sparse-arm", title="Add BM25 saturation and length normalisation to the sparse arm behind a flag",
  s=["S-25"], wave=3, area=["corpus","retrieval"], tier="Sonnet", size="M",
  why="The sparse arm is raw term frequency times IDF with no saturation or length normalisation although its docstring says 'BM25-style' (`rag/vector_index.py:112`); legacy main chunks are unbounded (8,487 chunks over 8,000 characters), so long chunks can dominate (RV-1 F-1.6). A sparse recompute is CPU-only, so bundling it with ligature repair 'to save cost' is wrong and would confound attribution (review S-25).",
  in_=["Index-time weight `tf*(k1+1)/(tf + k1*(1-b+b*len/avglen))` behind an explicit option, `avglen` measured once per corpus from stored chunks (CPU) and recorded; applies only when (re)computing sparse vectors (`app.resparse` on a clone); default off.","Starts only after EV-22 (S-17 done)."],
  out=["Edge-punctuation stripping in the tokenizer (measured effect on 12-26% of tokens, but it changes tokens; include only if the operator wants it in this A/B: stated as a separate flag, never bundled). Applying to any live collection. The A/B (CQ-18)."],
  owns=["rag/vector_index.py","rag/test_vector_index.py","rag/sparse_tokens.py","rag/test_sparse_tokens.py","app/resparse.py","app/test_resparse.py"],
  commits=["stub: docstring with the formula, parameters (k1, b, avglen), the default-off guarantee and the one-recompute-per-arm rule","failing tests: option off leaves vectors byte-identical; option on gives the expected weights on a toy corpus","implementation to green","avglen measurement helper and recorded constants per corpus"],
  verify=["Identical sparse vectors with the option off on 200 stored chunks (RQ-5 check reused)","`conda run -n agent-rag-research python -m pytest -q rag/test_vector_index.py rag/test_sparse_tokens.py app/test_resparse.py -o addopts=\"--disable-socket\"`"],
  accept="Option off: byte-identical vectors; option on: weights match a hand-computed toy example; avglen constants recorded with the command that produced them. Falsified if default behaviour changes by one byte.",
  deps=["EV-22","CQ-9","RQ-5"], gates=["CQ-18"],
  risk="Query-side tokens stay binary while index weights change, which a later reader might misread as a bug. Mitigation: documented in the docstring. Rollback: revert; no index depends on it.",
  docs="PROJECT-STATUS via EP-5."),

